package Controllers; import Services.OrderService; import java.io.*; import javax.servlet.*; import javax.servlet.annotation.WebServlet; import javax.servlet.http.*;
@WebServlet("/ViewOrderHistoryServlet") public class ViewOrderHistoryServlet extends HttpServlet{private final OrderService s=new OrderService();protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{r.setAttribute("orders",s.history());r.getRequestDispatcher("OrdersHistoryView.jsp").forward(r,p);}}
